import numpy as np


def create_probe():
    return LevelBiasProbe()


class LevelBiasProbe:
    def __init__(self):
        self.probe_id = "level-bias-mu2"

    def run(self, artifacts):
        e = np.asarray(artifacts["residuals"]["e"], dtype=np.float64)
        e = e[np.isfinite(e).all(axis=1)]
        blocks = 8
        size = e.shape[0] // blocks
        means = e[: size * blocks].reshape(blocks, size, e.shape[1]).mean(axis=1)
        return {"mu2": float(np.mean(means * means))}
